import{z as n,x as p,o as s,c as B,q as t,j as l,D as e,d as A,s as o,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"口令与加盐","description":"","frontmatter":{"title":"口令与加盐","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/password-salt.md","filePath":"cs/password-salt.md","lastUpdated":1791413859000}'),d={name:"cs/password-salt.md"};function m(h,a,u,D,c,f){const r=p("Mermaid");return s(),B("div",null,[a[2]||(a[2]=t('<h1 id="口令与加盐" tabindex="-1">口令与加盐 <a class="header-anchor" href="#口令与加盐" aria-label="Permalink to &quot;口令与加盐&quot;">​</a></h1><div class="epigraph"><p>库里不存口令原文；盐让同一口令不再撞成同一串，慢哈希让离线猜测变贵。</p><footer>—— 据 Morris and Thompson, Password Security, CACM 1979；Anderson 对口令存储的整理</footer></div><p><a href="/cs/cert-revoke">上一课</a>用证书绑机器与服务身份。本课不重做 X.509。缺口是：人带着可记忆的秘密来证明自己。口令熵通常远低于密钥，且会被复用。存储必须假设库会被抄走——<a href="/cs/threat-model">威胁模型</a>里的「磁盘与备份在边界内仍可能泄露」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>明文存口令，一份泄露则全部身份作废。只做一次哈希，彩虹表与预计算把常用口令一次对上所有用户。缺口不是再讲<a href="/cs/hash-collision">哈希与碰撞</a>的抗碰撞，而是口令专用：每用户随机盐、慢哈希（或内存硬函数），使离线猜测按「每一猜测 × 每一用户」付钱。在线猜测另用限速与锁定，那是认证协议课。</p><p><span class="marginnote">「盐」翻译成白话：存哈希前给口令拼一串每人不同的随机字符再哈希。类比给同一封信装进不同编号的信箱——信的内容没变，但抄表的人没法用一张「内容→信箱」对照表一次看穿所有信箱。</span></p><p><span class="marginnote">盐不是保密材料，可与哈希一起存。胡椒（pepper）是服务器侧额外密钥，丢了则全体无法验证，本课只点名，不做成默认。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>注册：抽盐，存 \\((\\mathit{salt}, H(\\mathit{salt}\\|\\mathit{password}))\\) 或标准口令哈希 API 的输出。验证：用同一盐重算比较。禁止「可逆加密口令」当默认：那把保密重新绑到另一把主密钥上，主密钥一丢仍全军覆没。本课不讨论口令强度 UI，只锁定存储布局。</p>',9)),(s(),l(i,null,{default:e(()=>[o(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PW%5B%22%E5%8F%A3%E4%BB%A4%22%5D%20--%3E%20SALT%5B%22%E6%AF%8F%E7%94%A8%E6%88%B7%E7%9B%90%22%5D%0A%20%20SALT%20--%3E%20SH%5B%22%E6%85%A2%E5%93%88%E5%B8%8C%22%5D%0A%20%20SH%20--%3E%20STORE%5B%22%E5%AD%98%E7%9B%90%E4%B8%8E%E6%91%98%E8%A6%81%22%5D%0A%20%20STORE%20--%3E%20AUTH%5B%22%E5%90%8E%E8%AF%BE%3A%20%E8%AE%A4%E8%AF%81%E5%8D%8F%E8%AE%AE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[A("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"盐打碎预计算表；慢哈希（迭代、内存困难）把 GPU 穷举的速率压下来。这不把弱口令变成密钥：在线与针对性猜测仍成立。完整轴：口令哈希不提供对会话的认证，只服务「核验人记得的秘密」。传输中口令必须走已认证的保密信道，否则盐与哈希都是事后。",-1)),a[5]||(a[5]=E("p",null,"同一口令在不同盐下摘要不同，泄漏一份哈希不能直接对上另一用户。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：一亿用户都用了「123456」。无盐时攻击者算一次 MD5，对着库扫一遍就能抓出全部中招者；每用户 16 字节随机盐后，同一个猜测要对一亿个不同的盐各算一遍——成本从 1 次哈希变成 1 亿次。注意盐不提高口令本身的熵，弱口令依然最先倒下，只是从「集体阵亡」变成「逐个点名」。")],-1)),(s(),l(i,null,{default:e(()=>[o(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20NS%5B%22%E6%97%A0%E7%9B%90%EF%BC%9A%E4%B8%80%E6%AC%A1%E8%AE%A1%E7%AE%97%E5%91%BD%E4%B8%AD%E6%89%80%E6%9C%89%E7%94%A8%E6%88%B7%22%5D%0A%20%20%20%20A1%5B%22%E7%AE%97%20H(%E5%8F%A3%E4%BB%A4)%20%E4%B8%80%E6%AC%A1%22%5D%20--%3E%20A2%5B%22%E5%85%A8%E5%BA%93%E6%AF%94%E5%AF%B9%EF%BC%9A%E7%A7%92%E7%BA%A7%E6%8A%93%E5%87%BA%E6%89%80%E6%9C%89%E7%9B%B8%E5%90%8C%E5%8F%A3%E4%BB%A4%22%5D%0A%20%20end%0A%20%20subgraph%20WS%5B%22%E7%9B%90%E5%8C%96%EF%BC%9A%E9%80%90%E7%94%A8%E6%88%B7%E4%BB%98%E9%92%B1%22%5D%0A%20%20%20%20B1%5B%22%E7%8C%9C%E4%B8%80%E4%B8%AA%E5%8F%A3%E4%BB%A4%22%5D%20--%3E%20B2%5B%22%E7%94%A8%E7%94%A8%E6%88%B7%201%20%E7%9A%84%E7%9B%90%E9%87%8D%E7%AE%97%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E7%94%A8%E7%94%A8%E6%88%B7%202%20%E7%9A%84%E7%9B%90%E9%87%8D%E7%AE%97%22%5D%0A%20%20%20%20B3%20--%3E%20B4%5B%22%E4%B8%80%E4%BA%BF%E7%94%A8%E6%88%B7%20%3D%20%E4%B8%80%E4%BA%BF%E6%AC%A1%E6%85%A2%E5%93%88%E5%B8%8C%22%5D%0A%20%20end%0A%20%20NS%20-.%20%22%E9%A2%84%E8%AE%A1%E7%AE%97%E8%A1%A8%E4%BD%9C%E5%BA%9F%22%20.-%3E%20WS%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把加盐写成「加密」。不要给具体破解步骤或词表攻击配方。本课也不把生物特征、硬件令牌写进存储格式。恢复流程（邮件重置）往往比哈希更弱，属于协议与运营，下一课会碰到认证的消息顺序。</p><p>口令复用使一次泄露变成多站身份事故；这是人的熵与威胁模型问题，不是盐算错。后课默认：口令核验针对盐化慢哈希；如何证明「我是这个用户」的消息往返，是认证协议。</p><p>传输中的口令必须走已认证保密信道。盐化存储保护的是盘上的抄本，不是线路上的明文。</p><p><span class="marginnote">初学者容易以为「加了盐就安全了」。盐和慢哈希只抬高离线猜测的成本，不改变口令本身的熵：针尖加了锁还是针尖。所以防线仍是组合拳——拒绝常见口令、慢哈希、再加上 MFA，单一措施都不够。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>离线猜测的代价由慢哈希与盐共同决定；在线猜测要限速，属下一课协议。</p></li><li><p>可逆「加密存口令」把全部身份绑到主密钥，本课不当默认。</p></li><li><p>证书绑服务；本课把人的秘密存成盐化慢哈希，假设库会泄露。</p></li><li><p>盐破预计算；慢哈希抬离线代价；弱口令仍弱。</p></li><li><p>核验之后如何建会话、防重放，是认证协议缺口。</p></li><li><p>出处：Morris and Thompson, 1979；Anderson, <em>Security Engineering</em>。</p></li></ul>',7))])}const T=n(d,[["render",m]]);export{S as __pageData,T as default};
